from .ast import Program
from .diagnostics import InternalCompilerError


def generate_llvm_ir(program: Program, source_name: str = "input.ocl") -> str:
    """Lower a program that has already passed `semantic.analyze`."""
    lines = [
        "; Generated by oclc 0.1",
        f'source_filename = "{source_name.replace(chr(34), "_")}"',
        "",
    ]
    for function in program.functions:
        if len(function.body) != 1:
            raise InternalCompilerError(
                f"function '{function.name}' reached codegen with {len(function.body)} statements; "
                "semantic analysis must run before lowering"
            )
        value = function.body[0].expression.value
        lines.extend((f"define i32 @{function.name}() {{", "entry:", f"  ret i32 {value}", "}", ""))
    return "\n".join(lines)
